/* A LINE CHART: which way it is going, with the scale that says by how much.
 *
 * The system had a <Sparkline> (a shape beside a number, no axes on purpose)
 * and a <BarChart> (categories), and nothing for the commonest analytical
 * question of all — one or more measures over time, read against a grid.
 *
 * The scale, the grid, the goal line, the readout, the legend and the row of
 * labels live in src/lib/chart.css: they are the same furniture every chart in
 * this system wears. What is here is the MARK — the lines, their dots and the
 * crosshair that reads them.
 */
.line-chart {
  /* Local to this component: the three heights a line chart is read at, the
   * width the scale column reserves, and the values set per element from the
   * data (declared so the stylesheet stands on its own). */
  --chart-height: calc(var(--space-16) * 1.75);
  --chart-scale-width: 2.5rem;
  --tick-at: 0%;
  --dot-x: 0%;
  --dot-y: 0%;

  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin: 0;
  min-inline-size: 0;
}
.line-chart[data-size="sm"] { --chart-height: var(--space-16); }
.line-chart[data-size="lg"] { --chart-height: calc(var(--space-16) * 2.5); }

.line-chart-plot {
  position: relative;
  flex: 1 1 auto;
  block-size: 100%;
  min-inline-size: 0;
  /* The whole plot is the hit area for the crosshair: a reader should not have
   * to find a 6px dot to be told what it says. */
  touch-action: none;
  cursor: crosshair;
}
.line-chart-plot > svg { display: block; inline-size: 100%; block-size: 100%; overflow: visible; }

/* THE LINE. 2px, round joins, and the plot wipes itself in once: the shape
 * arriving left to right is the same gesture the reader makes reading it.
 *
 * A WIPE, not a dash. The obvious way to draw a line on is a dash offset, and
 * it does not survive this SVG: `preserveAspectRatio="none"` stretches the
 * viewBox, `vector-effect: non-scaling-stroke` takes the stroke back out of
 * that stretch, and the dash pattern ends up measured in one space and drawn in
 * the other — the line came out in fragments with gaps between the months
 * (measured 23.08, both with a percentage dash and with pathLength="1"). A clip
 * on the plot is geometry the stretch does not touch. */
.line-chart-plot > svg {
  animation: line-chart-wipe var(--duration-slow) var(--ease-out) both;
}
@keyframes line-chart-wipe {
  from { clip-path: inset(0 100% 0 0); }
  to   { clip-path: inset(0); }
}
/* Right to left, the axis reads right to left, and so does the wipe. */
[dir="rtl"] .line-chart-plot > svg {
  transform: scaleX(-1);
  animation-name: line-chart-wipe-rtl;
}
@keyframes line-chart-wipe-rtl {
  from { clip-path: inset(0 0 0 100%); }
  to   { clip-path: inset(0); }
}

.line-chart-line {
  fill: none;
  stroke: var(--chart-1);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.line-chart-area {
  fill: var(--chart-1);
  opacity: 0.12;
}

/* THE SERIES SLOTS, in fixed order — never cycled, so a filter that drops a
 * line leaves the others the colour they were. */
.line-chart-series[data-series="2"] .line-chart-line { stroke: var(--chart-2); }
.line-chart-series[data-series="3"] .line-chart-line { stroke: var(--chart-3); }
.line-chart-series[data-series="4"] .line-chart-line { stroke: var(--chart-4); }
.line-chart-series[data-series="5"] .line-chart-line { stroke: var(--chart-5); }
.line-chart-series[data-series="6"] .line-chart-line { stroke: var(--chart-6); }
.line-chart-series[data-tone="success"] .line-chart-line { stroke: var(--chart-success); }
.line-chart-series[data-tone="warning"] .line-chart-line { stroke: var(--chart-warning); }
.line-chart-series[data-tone="danger"]  .line-chart-line { stroke: var(--chart-danger); }

/* THE CROSSHAIR AND ITS DOTS. One vertical rule, one dot per series, so every
 * line is read at the same x. */
.line-chart-crosshair {
  position: absolute;
  inset-block: 0;
  inset-inline-start: var(--dot-x);
  inline-size: 1px;
  background: var(--chart-grid);
  pointer-events: none;
}
.line-chart-dot {
  position: absolute;
  inset-inline-start: var(--dot-x);
  inset-block-start: var(--dot-y);
  inline-size: var(--space-2);
  block-size: var(--space-2);
  margin-inline-start: calc(var(--space-2) / -2);
  margin-block-start: calc(var(--space-2) / -2);
  border-radius: var(--radius-full);
  background: var(--chart-1);
  /* A ring in the surface colour, so a dot that lands on a grid line or on
   * another series still reads as one mark. */
  box-shadow: 0 0 0 var(--space-2xs) var(--card);
  pointer-events: none;
}
.line-chart-dot[data-series="2"] { background: var(--chart-2); }
.line-chart-dot[data-series="3"] { background: var(--chart-3); }
.line-chart-dot[data-series="4"] { background: var(--chart-4); }
.line-chart-dot[data-series="5"] { background: var(--chart-5); }
.line-chart-dot[data-series="6"] { background: var(--chart-6); }
.line-chart-dot[data-tone="success"] { background: var(--chart-success); }
.line-chart-dot[data-tone="warning"] { background: var(--chart-warning); }
.line-chart-dot[data-tone="danger"]  { background: var(--chart-danger); }

/* The ends of a line are POINTS, not the middles of columns: the first and last
 * labels sit under them rather than over a slot that is not there. */
.line-chart .chart-labels > span:first-child { text-align: start; }
.line-chart .chart-labels > span:last-child { text-align: end; }

/* In a card the chart takes the spare height, the same way <BarChart> does. */
.card > .line-chart { flex: 1 1 auto; }
.card > .line-chart .chart-frame {
  block-size: auto;
  min-block-size: var(--chart-height);
  flex: 1 1 auto;
}

import '../../lib/chart.css'
import './LineChart.css'
import { type CSSProperties, type PointerEvent, useRef, useState } from 'react'
import { cn } from '../lib/cn'
import { areaPath, formatValue, linePath, scaleFor } from '../lib/chart'

type Size = 'sm' | 'md' | 'lg'

export type LineSeries = {
  /** What this line is. Names it in the legend and in the crosshair readout. */
  label: string
  /** One value per point of `labels`, in the same order. */
  values: number[]
  /** A status tone instead of the next series colour — for a line that MEANS
   *  late or over budget. Otherwise the slot colour, in fixed order. */
  tone?: 'success' | 'warning' | 'danger'
}

type Props = {
  /** The x axis, oldest first: months, weeks, sites. */
  labels: string[]
  /** One entry per line. Two or more bring a legend with them. */
  series: LineSeries[]
  /** Fills under the line. For ONE series only: two filled areas overlapping
   *  is a chart nobody can read. */
  area?: boolean
  /** Top of the scale. Defaults to the first nice number above the data. */
  max?: number
  /** A goal drawn across the plot. Its own label is deliberately not a prop: a
   *  word printed inside the plot sits on the lines (owner, 23.08). Name the
   *  goal in the card's meta line. */
  target?: number
  size?: Size
  /** The scale down the side and the grid with it. On by default. */
  axis?: boolean
  /** What the chart measures. Names it for a screen reader, which reads the
   *  table this component renders for it. */
  label?: string
  /** BCP-47 tag for the numbers. Omit to follow the browser. */
  locale?: string
  className?: string
}

/* The drawing space. The viewBox is fixed and the SVG stretches to the card;
 * strokes are held even with vector-effect so a wide card does not draw a fat
 * line and a narrow one a thin one. */
const W = 100
const H = 40

/** A value over time, as a line: the analytical card's first form when the
 *  question is "which way is it going". Carries its own scale, grid, legend and
 *  a crosshair readout, and reads as a table to a screen reader. Reach for
 *  <Sparkline> when the shape sits beside a number and needs no axis, and for
 *  <BarChart> when the x axis is categories rather than time. 
 *
 * Copy: the accessible label says what the line measures and over what period.
 * Series names are the things themselves, because a legend of "Series 1"
 * is a legend of nothing.
 */
export function LineChart({
  labels,
  series,
  area,
  max,
  target,
  size,
  axis = true,
  label,
  locale,
  className,
}: Props) {
  const [at, setAt] = useState<number | null>(null)
  const plotRef = useRef<HTMLDivElement>(null)

  if (!labels.length || !series.length) return null

  const all = series.flatMap((s) => s.values)
  const scale = scaleFor([...all, ...(max != null ? [max] : []), ...(target != null ? [target] : [])])
  const top = max ?? scale.max
  const ticks = max != null ? scaleFor([max]).ticks : scale.ticks
  const format = (v: number) => formatValue(v, locale)

  const step = labels.length > 1 ? W / (labels.length - 1) : 0
  const pointsOf = (values: number[]) =>
    values.map((v, i) => [labels.length > 1 ? i * step : W / 2, H - (Math.max(0, Math.min(top, v)) / top) * H] as const)
  const pct = (v: number) => `${Math.max(0, Math.min(100, (v / top) * 100))}%`

  /* Which point the pointer is nearest. One crosshair for every line at once,
   * because the reader is comparing them at that x — not hunting one dot. */
  const track = (e: PointerEvent<HTMLDivElement>) => {
    const box = plotRef.current?.getBoundingClientRect()
    if (!box || box.width === 0) return
    const ratio = (e.clientX - box.left) / box.width
    const flipped = getComputedStyle(plotRef.current as Element).direction === 'rtl' ? 1 - ratio : ratio
    setAt(Math.max(0, Math.min(labels.length - 1, Math.round(flipped * (labels.length - 1)))))
  }

  return (
    <figure
      className={cn('line-chart', className)}
      data-size={size}
      data-axis={axis ? '' : undefined}
      data-area={area && series.length === 1 ? '' : undefined}
    >
      <div className="chart-frame">
        {axis && (
          <div className="chart-scale" aria-hidden="true">
            {ticks.map((t) => (
              <span key={t} className="chart-tick" style={{ '--tick-at': pct(t) } as CSSProperties}>
                {format(t)}
              </span>
            ))}
          </div>
        )}

        <div
          className="line-chart-plot"
          ref={plotRef}
          onPointerMove={track}
          onPointerLeave={() => setAt(null)}
        >
          {axis &&
            ticks.map((t) => (
              <span key={t} className="chart-grid" style={{ '--tick-at': pct(t) } as CSSProperties} aria-hidden="true" />
            ))}

          {target != null && (
            <span className="chart-target" style={{ '--tick-at': pct(target) } as CSSProperties} aria-hidden="true" />
          )}

          <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" aria-hidden="true" focusable="false">
            {series.map((s, k) => {
              const pts = pointsOf(s.values)
              return (
                <g key={s.label} className="line-chart-series" data-series={k + 1} data-tone={s.tone}>
                  {area && series.length === 1 && <path className="line-chart-area" d={areaPath(pts, H)} />}
                  <path className="line-chart-line" d={linePath(pts)} vectorEffect="non-scaling-stroke" />
                </g>
              )
            })}
          </svg>

          {/* The dots ride on top as real elements, so stretching the plot
              cannot turn a circle into an ellipse. */}
          {at != null &&
            series.map((s, k) => (
              <span
                key={s.label}
                className="line-chart-dot"
                data-series={k + 1}
                data-tone={s.tone}
                style={
                  {
                    '--dot-x': `${(at / Math.max(1, labels.length - 1)) * 100}%`,
                    '--dot-y': `${(1 - Math.max(0, Math.min(top, s.values[at] ?? 0)) / top) * 100}%`,
                  } as CSSProperties
                }
                aria-hidden="true"
              />
            ))}

          {at != null && (
            <span
              className="line-chart-crosshair"
              style={{ '--dot-x': `${(at / Math.max(1, labels.length - 1)) * 100}%` } as CSSProperties}
              aria-hidden="true"
            />
          )}

          {at != null && (
            <div
              className="chart-readout"
              data-side={at > labels.length / 2 ? 'start' : 'end'}
              style={{ '--dot-x': `${(at / Math.max(1, labels.length - 1)) * 100}%` } as CSSProperties}
              aria-hidden="true"
            >
              <span className="chart-readout-label">{labels[at]}</span>
              {series.map((s, k) => (
                <span key={s.label} className="chart-readout-row">
                  <span className="chart-key" data-shape="dot" data-series={k + 1} data-tone={s.tone} />
                  {series.length > 1 && <span>{s.label}</span>}
                  <span className="chart-readout-value">{format(s.values[at] ?? 0)}</span>
                </span>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="chart-labels" aria-hidden="true">
        {labels.map((l, i) => (
          <span key={l} data-active={at === i ? '' : undefined}>
            {l}
          </span>
        ))}
      </div>

      {series.length > 1 && (
        <ul className="chart-legend" aria-hidden="true">
          {series.map((s, k) => (
            <li key={s.label}>
              <span className="chart-key" data-shape="dot" data-series={k + 1} data-tone={s.tone} />
              {s.label}
            </li>
          ))}
        </ul>
      )}

      <table className="sr-only">
        {label && <caption>{label}</caption>}
        <thead>
          <tr>
            <th scope="col">Point</th>
            {series.map((s) => (
              <th scope="col" key={s.label}>
                {s.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {labels.map((l, i) => (
            <tr key={l}>
              <th scope="row">{l}</th>
              {series.map((s) => (
                <td key={s.label}>{format(s.values[i] ?? 0)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  )
}
